Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
RDMA/rxe: Reject non-8-byte ATOMIC_WRITE payloads

atomic_write_reply() at drivers/infiniband/sw/rxe/rxe_resp.c
unconditionally dereferences 8 bytes at payload_addr(pkt):

    value = *(u64 *)payload_addr(pkt);

check_rkey() previously accepted an ATOMIC_WRITE request with pktlen ==
resid == 0 because the length validation only compared pktlen against
resid. A remote initiator that sets the RETH length to 0 therefore reaches
atomic_write_reply() with a zero-byte logical payload, and the responder
reads sizeof(u64) bytes from past the logical end of the packet into
skb->head tailroom, then writes those 8 bytes into the attacker's MR via
rxe_mr_do_atomic_write(). That is a remote disclosure of 4 bytes of kernel
tailroom per probe (the other 4 bytes are the packet's own trailing ICRC).

IBA oA19-28 defines ATOMIC_WRITE as exactly 8 bytes. Anything else is
protocol-invalid. Hoist a strict length check into check_rkey() so the
responder never reaches the unchecked dereference, and keep the existing
WRITE-family length logic for the normal RDMA WRITE path.

Reproduced on mainline with an unmodified rxe driver: a sustained
zero-length ATOMIC_WRITE probe repeatedly leaks adjacent skb head-buffer
bytes into the attacker's MR, including recognisable kernel strings and
partial kernel-direct-map pointer words.  With this patch applied the
responder rejects the PDU and the MR stays all-zero.

Cc: stable@vger.kernel.org
Fixes: 034e285f8b99 ("RDMA/rxe: Make responder support atomic write on RC service")
Link: https://patch.msgid.link/r/20260418162141.3610201-1-michael.bommarito@gmail.com
Assisted-by: Claude:claude-opus-4-7
Signed-off-by: Michael Bommarito <michael.bommarito@gmail.com>
Reviewed-by: Zhu Yanjun <yanjun.zhu@linux.dev>
Signed-off-by: Jason Gunthorpe <jgg@nvidia.com>

Here is the root cause:
The check_rkey() function only compared pktlen against resid for ATOMIC_WRITE requests, but did not enforce that the payload must be exactly 8 bytes as per the IB specification. This allowed a zero-length ATOMIC_WRITE to pass validation, leading to an out-of-bounds read of 8 bytes from the skb tailroom when atomic_write_reply() unconditionally dereferences payload_addr(pkt).

Here is the patch:
  */
 static enum resp_states check_rkey(struct rxe_qp *qp,
 				   struct rxe_pkt_info *pkt)
 {
 	struct rxe_mr *mr = NULL;
 	struct rxe_mw *mw = NULL;
 	u64 va;
 	u32 rkey;
 	u32 resid;
 	u32 pktlen;
 	int mtu = qp->mtu;
 	enum resp_states state;
 	int access = 0;

 	/* parse RETH or ATMETH header for first/only packets
 	 * for va, length, rkey, etc. or use current value for
 	 * middle/last packets.
 	 */
 	if (pkt->mask & (RXE_READ_OR_WRITE_MASK | RXE_ATOMIC_WRITE_MASK)) {
 		if (pkt->mask & RXE_RETH_MASK)
 			qp_resp_from_reth(qp, pkt);

 		access = (pkt->mask & RXE_READ_MASK) ? IB_ACCESS_REMOTE_READ
 						     : IB_ACCESS_REMOTE_WRITE;
 	} else if (pkt->mask & RXE_FLUSH_MASK) {
 		u32 flush_type = feth_plt(pkt);

 		if (pkt->mask & RXE_RETH_MASK)
 			qp_resp_from_reth(qp, pkt);

 		if (flush_type & IB_FLUSH_GLOBAL)
 			access |= IB_ACCESS_FLUSH_GLOBAL;
 		if (flush_type & IB_FLUSH_PERSISTENT)
 			access |= IB_ACCESS_FLUSH_PERSISTENT;
 	} else if (pkt->mask & RXE_ATOMIC_MASK) {
 		qp_resp_from_atmeth(qp, pkt);
 		access = IB_ACCESS_REMOTE_ATOMIC;
 	} else {
 		/* shouldn't happen */
 		WARN_ON(1);
 	}

 	/* A zero-byte read or write op is not required to
 	 * set an addr or rkey. See C9-88
 	 */
 	if ((pkt->mask & RXE_READ_OR_WRITE_MASK) &&
 	    (pkt->mask & RXE_RETH_MASK) && reth_len(pkt) == 0) {
 		qp->resp.mr = NULL;
 		return RESPST_EXECUTE;
 	}

 	va	= qp->resp.va;
 	rkey	= qp->resp.rkey;
 	resid	= qp->resp.resid;
 	pktlen	= payload_size(pkt);

 	if (rkey_is_mw(rkey)) {
 		mw = rxe_lookup_mw(qp, access, rkey);
 		if (!mw) {
 			rxe_dbg_qp(qp, "no MW matches rkey %#x\n", rkey);
 			state = get_rkey_violation_state(pkt);
 			goto err;
 		}

 		mr = mw->mr;
 		if (!mr) {
 			rxe_dbg_qp(qp, "MW doesn't have an MR\n");
 			state = get_rkey_violation_state(pkt);
 			goto err;
 		}

 		if (mw->access & IB_ZERO_BASED)
 			qp->resp.offset = mw->addr;

 		rxe_get(mr);
 		rxe_put(mw);
 		mw = NULL;
 	} else {
 		mr = lookup_mr(qp->pd, access, rkey, RXE_LOOKUP_REMOTE);
 		if (!mr) {
 			rxe_dbg_qp(qp, "no MR matches rkey %#x\n", rkey);
 			state = get_rkey_violation_state(pkt);
 			goto err;
 		}
 	}

 	if (pkt->mask & RXE_FLUSH_MASK) {
 		/* FLUSH MR may not set va or resid
 		 * no need to check range since we will flush whole mr
 		 */
 		if (feth_sel(pkt) == IB_FLUSH_MR)
 			goto skip_check_range;
 	}

 	if (mr_check_range(mr, va + qp->resp.offset, resid)) {
 		state = get_rkey_violation_state(pkt);
 		goto err;
 	}

 skip_check_range:
-	if (pkt->mask & (RXE_WRITE_MASK | RXE_ATOMIC_WRITE_MASK)) {
+	if (pkt->mask & RXE_ATOMIC_WRITE_MASK) {
+		/* IBA oA19-28: ATOMIC_WRITE payload is exactly 8 bytes.
+		 * Reject any other length before the responder reads
+		 * sizeof(u64) bytes from payload_addr(pkt); a shorter
+		 * payload would read past the logical end of the packet
+		 * into skb->head tailroom.
+		 */
+		if (resid != sizeof(u64) || pktlen != sizeof(u64) ||
+		    bth_pad(pkt)) {
+			state = RESPST_ERR_LENGTH;
+			goto err;
+		}
+	} else if (pkt->mask & RXE_WRITE_MASK) {
 		if (resid > mtu) {
 			if (pktlen != mtu || bth_pad(pkt)) {
 				state = RESPST_ERR_LENGTH;
 				goto err;
 			}
 		} else {
 			if (pktlen != resid) {
 				state = RESPST_ERR_LENGTH;
 				goto err;
 			}
 			if ((bth_pad(pkt) != (0x3 & (-resid)))) {
 				/* This case may not be exactly that
 				 * but nothing else fits.
 				 */
 				state = RESPST_ERR_LENGTH;
 				goto err;
 			}
 		}
 	}

 	WARN_ON_ONCE(qp->resp.mr);

 	qp->resp.mr = mr;
 	return RESPST_EXECUTE;

 err:
 	qp->resp.mr = NULL;
 	if (mr)
 		rxe_put(mr);
 	if (mw)
 		rxe_put(mw);

 	return state;
 }



